{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Services — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Clinical, safety-forward aromatherapy sessions and membership options that may support daily balance." />
  <style>
    :root{--bg:#fbf9f6;--card:#ffffff;--muted:#6b6b6b;--accent:#6aa84f;--accent-2:#6b8eeb;--glass:rgba(255,255,255,0.85);--maxw:1100px}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45;color:#222;margin:0;background:linear-gradient(180deg,var(--bg),#f4f6f8);}
    header{background:linear-gradient(180deg,rgba(106,168,79,0.06),transparent);border-bottom:1px solid rgba(0,0,0,0.04)}
    .wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
    nav{display:flex;gap:18px;align-items:center;justify-content:space-between}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.4px}
    .navlinks{display:flex;gap:12px}
    .navlinks a{color:#334;font-size:14px;text-decoration:none;padding:8px 10px;border-radius:8px}
    .navlinks a.cta{background:var(--accent);color:white;padding:8px 12px}
    main{padding:32px 0}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center;background-image:url('assets/img/pattern.svg');background-size:520px;background-repeat:no-repeat;background-position:calc(100% - 10px) top;padding:28px;border-radius:14px}
    .hero h1{margin:0;font-size:28px}
    .muted{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-top:18px}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(20,20,40,0.04)}
    .small{font-size:14px;color:var(--muted)}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#f1f7e8;color:#385c1f;font-weight:600}
    .section{margin:26px 0}

    /* reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease,transform 420ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;transform:none;opacity:1}
    }

    /* modal */
    .overlay{position:fixed;inset:0;background:rgba(8,10,12,0.45);display:none;align-items:center;justify-content:center;padding:20px}
    .overlay.open{display:flex}
    .modal{width:100%;max-width:680px;background:var(--card);border-radius:12px;padding:22px;box-shadow:0 10px 30px rgba(10,20,30,0.12)}
    .modal h3{margin-top:0}
    .controls{display:flex;gap:8px;align-items:center}
    .btn{background:var(--accent-2);border:none;color:white;padding:8px 12px;border-radius:8px;cursor:pointer}
    .btn.secondary{background:#eee;color:#222}
    footer{padding:28px 0;color:var(--muted);font-size:13px}

    /* responsive */
    @media (max-width:800px){.grid{grid-template-columns:1fr}.hero{background-position:top right}} 
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div class="navlinks">
          <a href="index.html">Home</a>
          <a href="services.html" aria-current="page">Offerings</a>
          <a href="blends.html">Blends</a>
          <a href="shop.html">Boutique</a>
          <a href="pricing.html">Plans</a>
          <a href="about.html">About</a>
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero section">
      <div class="reveal">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex-wrap:wrap">
          <div style="flex:1;min-width:260px">
            <div class="pill">Clinical • safety-first</div>
            <h1>Personal aromatherapy plans that may support daily regulation</h1>
            <p class="small muted">Short, guided sessions and ongoing membership access designed for steady, repeatable scent practices. All guidance is safety-forward and non-medical.</p>
            <div style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap">
              <button class="btn" id="openExercise">Try a brief guided exercise</button>
              <a class="btn secondary" href="book.html">Book an intake</a>
            </div>
          </div>
          <div style="width:280px;min-width:220px">
            <div class="card small">
              <strong>Membership preview</strong>
              <p class="small muted">Monthly access to a library of guided scent practices, a quarterly one-on-one session, and member-only blends.</p>
              <div style="margin-top:10px"><a href="pricing.html" class="small">See plans →</a></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section reveal">
      <h2>How we work — a structured approach</h2>
      <div class="grid" style="margin-top:12px">
        <div class="card">
          <h3>Intake & context</h3>
          <p class="small muted">A detailed intake identifies routine, sensitivities, and household considerations — particularly pets, pregnancy, and medication interactions. We document safety preferences first.</p>
        </div>
        <div class="card">
          <h3>Practice design</h3>
          <p class="small muted">We design short rituals — micro-practices for breath, scent focus, and journaling — that fit your day. Each practice includes dilution guidance and patch-test steps.</p>
        </div>
      </div>
    </section>

    <section class="section reveal">
      <h2>Offerings</h2>
      <div class="grid" style="margin-top:10px">
        <div class="card">
          <h3>One-on-one Scent Session</h3>
          <p class="small muted">60-minute consult and practice design. Includes take-home dilution sheet and safe-use notes. Sessions may support momentary calm and clearer focus.</p>
          <div style="margin-top:8px"><strong>Single session</strong> — $95</div>
        </div>
        <div class="card">
          <h3>Group Micro-Rituals</h3>
          <p class="small muted">45-minute live group classes focusing on breath and scent sequences. Accessible pacing and clear safety comments for shared environments.</p>
          <div style="margin-top:8px"><strong>Drop-in</strong> — $18</div>
        </div>
        <div class="card">
          <h3>Scent Circle Membership</h3>
          <p class="small muted">Monthly membership with a curated blend, guided practice library, and quarterly check-in. A practical framing: pay for ongoing access rather than per-session billing.</p>
          <div style="margin-top:8px"><strong>From</strong> — $28/mo</div>
        </div>
        <div class="card">
          <h3>Workplace Workshops</h3>
          <p class="small muted">Short staff sessions emphasizing sensory safety and inclusive scent options. We avoid strong exposures and offer fragrance-free alternatives.</p>
        </div>
      </div>
    </section>

    <section class="section reveal">
      <h2>Frequently asked safety questions</h2>
      <div class="card" style="margin-top:12px">
        <h4>Dilution & patch testing</h4>
        <p class="small muted">All blends include recommended dilutions (e.g., 1–2% for adults) and a simple patch-test procedure. Always test on a small skin area and wait 24 hours before wider use.</p>
        <h4>Pets & shared spaces</h4>
        <p class="small muted">Essential oils can affect animals differently. We offer pet-safe alternatives and guidance to avoid prolonged exposures in shared areas.</p>
        <h4>Pregnancy & health conditions</h4>
        <p class="small muted">Some oils are not recommended during pregnancy or certain conditions. We review contraindications in intake and make non-scent strategies available. This service is not medical advice.</p>
      </div>
    </section>

    <section class="section reveal">
      <h2>Client notes</h2>
      <div class="grid" style="margin-top:12px">
        <div class="card">
          <p class="small">"Clear guidance, practical routines I actually use." — A. in {{CITY}}</p>
        </div>
        <div class="card">
          <p class="small">"I appreciate the safety-first checks — helpful for family and pets." — R., {{STATE}}</p>
        </div>
      </div>
    </section>

    <section class="section reveal" style="text-align:center">
      <a href="book.html" class="btn">Schedule an intake</a>
      <a href="pricing.html" class="btn secondary" style="margin-left:10px">Explore membership</a>
    </section>
  </main>

  <footer class="wrap">
    <div class="small muted">Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="overlay" class="overlay" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="exerciseTitle">
      <h3 id="exerciseTitle">Guided micro-practice</h3>
      <p class="small muted">A short 4-step practice: settle, breathe, scent-focus, journal. No strong smells required — you can imagine a scent if you prefer.</p>
      <div id="stepArea" style="margin-top:12px">
        <div id="stepText" style="font-weight:600">Ready?</div>
        <div id="timer" style="margin-top:10px;color:var(--muted)"></div>
      </div>
      <div style="margin-top:14px;display:flex;justify-content:space-between;align-items:center">
        <div class="controls">
          <button class="btn" id="startBtn">Start</button>
          <button class="btn secondary" id="nextBtn" disabled>Next</button>
        </div>
        <button class="btn secondary" id="closeBtn">Close</button>
      </div>
    </div>
  </div>

  <script>
    (function(){
      // Scroll reveal with reduced-motion support
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var revealEls = document.querySelectorAll('.reveal');
      if(prefersReduced){
        revealEls.forEach(function(el){el.classList.add('visible')});
      } else if('IntersectionObserver' in window){
        var obs = new IntersectionObserver(function(entries){
          entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}},{threshold:0.12})
        );
        revealEls.forEach(function(el){obs.observe(el)});
      } else { // fallback
        revealEls.forEach(function(el){el.classList.add('visible')});
      }

      // Guided exercise modal logic
      var overlay = document.getElementById('overlay');
      var openBtn = document.getElementById('openExercise');
      var closeBtn = document.getElementById('closeBtn');
      var startBtn = document.getElementById('startBtn');
      var nextBtn = document.getElementById('nextBtn');
      var stepText = document.getElementById('stepText');
      var timer = document.getElementById('timer');
      var steps = [
        {label:'Settle: sit comfortably', seconds:8},
        {label:'Breath: inhale 4s, exhale 6s, repeat', seconds:24},
        {label:'Scent-focus: briefly inhale and note qualities', seconds:14},
        {label:'Journal/intention: note one word', seconds:18}
      ];
      var idx = -1, tId = null, count=0;

      function showOverlay(){overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');}
      function hideOverlay(){overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');stopTimer();reset();}

      openBtn.addEventListener('click',showOverlay);
      closeBtn.addEventListener('click',hideOverlay);
      overlay.addEventListener('click',function(e){if(e.target===overlay) hideOverlay();});

      function startStep(i){
        idx = i; var s = steps[i];
        stepText.textContent = s.label;
        count = s.seconds;
        timer.textContent = count + 's';
        nextBtn.disabled = true; startBtn.disabled = true;
        tId = setInterval(function(){
          count--; if(count<=0){stopTimer();nextBtn.disabled=false;startBtn.disabled=false;timer.textContent='';}
          else timer.textContent = count + 's';
        },1000);
      }
      function stopTimer(){if(tId){clearInterval(tId);tId=null}}
      function reset(){idx=-1;stepText.textContent='Ready?';timer.textContent='';startBtn.disabled=false;nextBtn.disabled=true}

      startBtn.addEventListener('click',function(){ if(idx<0) startStep(0); else startStep(idx); });
      nextBtn.addEventListener('click',function(){ if(idx < steps.length-1) startStep(idx+1); else { stepText.textContent='Done — note one thing you noticed'; timer.textContent=''; nextBtn.disabled=true; } });

      // Accessibility: keyboard
      document.addEventListener('keydown',function(e){if(e.key==='Escape' && overlay.classList.contains('open')) hideOverlay()});

    })();
  </script>
</body>
</html>"} 
{"path":"blends.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Blends & Guides — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Curated blend suggestions and safe-use guidance for everyday aromatic practices." />
  <style>
    :root{--bg:#ffffff;--card:#fbfcff;--muted:#616161;--accent:#8a6fb1;--maxw:1100px}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;margin:0;background:var(--bg);color:#1b1b1b}
    .wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
    header{padding:10px 0;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav{display:flex;justify-content:space-between;align-items:center}
    .navlinks{display:flex;gap:12px}
    .navlinks a{text-decoration:none;color:#2b2b2b;padding:6px 8px;border-radius:8px}
    .brand{font-weight:700;color:var(--accent)}
    .hero{padding:22px;border-radius:12px;background:linear-gradient(180deg,rgba(138,111,177,0.06),transparent);display:flex;gap:18px;align-items:center}
    .hero h1{margin:0}
    .muted{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .blend{background:var(--card);padding:14px;border-radius:10px}
    .blend h4{margin:0 0 8px 0}
    .note{font-size:13px;color:var(--muted)}

    .reveal{opacity:0;transform:translateY(10px);transition:all 360ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media (max-width:600px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div class="navlinks">
          <a href="index.html">Home</a>
          <a href="services.html">Offerings</a>
          <a href="blends.html" aria-current="page">Blends</a>
          <a href="shop.html">Boutique</a>
          <a href="contact.html">Connect</a>
        </div>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero reveal">
      <div style="flex:1">
        <h1>Blends designed for short practices</h1>
        <p class="note">Each blend comes with suggested dilution ranges and simple notes for patch-testing. Avoid using concentrated essential oils directly on skin.</p>
      </div>
      <div style="width:220px;text-align:right">
        <a class="btn" href="shop.html" style="background:var(--accent);color:white;padding:8px 12px;border-radius:8px;text-decoration:none">Explore blends</a>
      </div>
    </section>

    <section class="section reveal" style="margin-top:18px">
      <h2>Featured formulations</h2>
      <div class="grid" style="margin-top:12px">
        <div class="blend">
          <h4>Morning Clarity — 2% suggested</h4>
          <p class="note">Bright citrus top with a soft herbal base. Use briefly in a diffuser or inhale from a tissue for a short focus cue.</p>
        </div>
        <div class="blend">
          <h4>Evening Ease — 1% suggested</h4>
          <p class="note">A gentle floral-woody combination meant for short evening rituals. Avoid near infants and consult if pregnant.</p>
        </div>
        <div class="blend">
          <h4>Pause Protocol — 1–1.5%</h4>
          <p class="note">Designed for quick breath practices; minimal and straightforward. Good for shared spaces when used briefly.</p>
        </div>
        <div class="blend">
          <h4>Work Reset — 1.5% suggested</h4>
          <p class="note">A crisp, clean profile to cue a mental reset during work breaks. Keep diffuser timers short and ventilate well.</p>
        </div>
        <div class="blend">
          <h4>Grounding Blend — 2% suggested</h4>
          <p class="note">Deeper base notes for a short grounding ritual. Consider pet sensitivities; use lower dilution in small spaces.</p>
        </div>
        <div class="blend">
          <h4>Neutralizer — spray formula</h4>
          <p class="note">A low-strength spray for fabrics and air; avoid direct skin contact. Patch-test fabrics first.</p>
        </div>
      </div>
    </section>

    <section class="section reveal" style="margin-top:18px">
      <h2>Guides & safe use</h2>
      <div class="blend" style="margin-top:12px">
        <h4>Simple dilution guide</h4>
        <p class="note">A quick frame: 1% ≈ 6 drops per 30ml carrier; 2% ≈ 12 drops per 30ml. Use lower strengths for children, older adults, pregnancy, and households with pets.</p>
        <h4>Patch-test</h4>
        <p class="note">Apply a diluted drop to inner forearm and observe 24 hours. If irritation occurs, discontinue and consult a clinician.</p>
      </div>
    </section>

    <section class="section reveal" style="margin-top:18px">
      <h2>Try a quick scent-focus</h2>
      <p class="note">You can run a guided micro-practice from any page. It is brief and does not require a physical scent — you may imagine aromas.</p>
      <div style="margin-top:10px"><button id="openExercise" style="padding:10px 12px;border-radius:8px;border:none;background:var(--accent);color:white">Try it now</button></div>
    </section>

  </main>

  <footer class="wrap" style="padding-top:18px;border-top:1px solid rgba(0,0,0,0.04);color:var(--muted)">
    <div>Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
  </footer>

  <!-- Lightweight guided modal (same script pattern) -->
  <div id="overlay" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,0.36);">
    <div style="background:white;padding:18px;border-radius:10px;max-width:560px;width:100%">
      <h3 id="title">Scent focus — quick</h3>
      <p class="note">Follow the prompts: settle, breathe, brief scent attention, note one word.</p>
      <div id="stepText" style="font-weight:600;margin-top:10px">Ready?</div>
      <div style="margin-top:12px;display:flex;gap:8px"><button id="startBtn" style="background:var(--accent);color:white;border:none;padding:8px 12px;border-radius:8px">Start</button><button id="closeBtn" style="background:#eee;border:none;padding:8px 12px;border-radius:8px">Close</button></div>
    </div>
  </div>

  <script>
    (function(){
      // reveal
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var list = document.querySelectorAll('.reveal');
      if(prefersReduced) {list.forEach(function(i){i.classList.add('visible')});}
      else if('IntersectionObserver' in window){
        var o = new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}}),{threshold:0.14}});
        list.forEach(function(i){o.observe(i)});
      } else {list.forEach(function(i){i.classList.add('visible')});}

      // modal
      var overlay = document.getElementById('overlay');
      var open = document.getElementById('openExercise');
      var start = document.getElementById('startBtn');
      var close = document.getElementById('closeBtn');
      var stepText = document.getElementById('stepText');
      var steps = ['Settle for 6s','Breathe slowly: 4 in, 6 out for 20s','Scent note: what stands out? 12s','Write one word or hold it in mind'];
      var idx=-1, t=null, timeLeft=0;

      open.addEventListener('click',function(){overlay.style.display='flex';overlay.setAttribute('aria-hidden','false');idx=-1;stepText.textContent='Ready?';});
      close.addEventListener('click',function(){overlay.style.display='none';overlay.setAttribute('aria-hidden','true');stop();});
      start.addEventListener('click',function(){if(idx<steps.length-1) next();});

      function next(){idx++; stepText.textContent=steps[idx]; if(idx===steps.length-1){start.textContent='Done'} }
      function stop(){clearTimeout(t);}
    })();
  </script>
</body>
</html>"} 
