      function updateCount(){var sum=0;for(var k in cart) sum+=cart[k];document.getElementById('count').textContent=sum}
      buttons.forEach(function(b){b.addEventListener('click',function(){var id=b.getAttribute('data-id');cart[id]=(cart[id]||0)+1;localStorage.setItem('cart',JSON.stringify(cart));updateCount();b.textContent='Added';setTimeout(function(){b.textContent='Add to cart'},900)})});
      updateCount();

      // Simple cart view
      document.getElementById('cartBtn').addEventListener('click',function(){
        var details = Object.keys(cart).length?Object.keys(cart).map(function(k){return k+': '+cart[k]}).join('\n'):'Cart is empty';
        alert(details);
      });

      // scroll reveal: prefer reduced motion
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var els = document.querySelectorAll('.product');
      if(prefersReduced) els.forEach(function(e){e.style.opacity=1});
      else if('IntersectionObserver' in window){
        var io = new IntersectionObserver(function(entries){entries.forEach(function(ent){if(ent.isIntersecting){ent.target.style.transition='opacity 360ms ease,transform 360ms ease';ent.target.style.opacity=1;ent.target.style.transform='none';io.unobserve(ent.target)}}),{threshold:0.08}});
        els.forEach(function(el){el.style.opacity=0;el.style.transform='translateY(10px)';io.observe(el)});
      } else els.forEach(function(e){e.style.opacity=1});

    })();
  </script>
